"""Coordinator-authored source-first seed for the queued Dead Last game chat."""
from pathlib import Path
import hashlib
import json

base = Path(__file__).parent / "prepared-dead-last-bank"
base.mkdir(exist_ok=False)
entries = [
    ("How does each player prepare their ID and Voting cards, what happens to cards for unused colors, and how is the initial Gold Bar pool dealt?", "Stand a visible ID in your chosen color, take the matching Voting set, remove target cards for colors not playing, and retain your Ambush card. Put the Gold deck face down and deal four central Gold Bar cards with values hidden.", [3]),
    ("Is there a player-by-player voting turn order? When may a player change their face-down choice, and when are choices revealed?", "There is no turn order. Choices can change until reveal. Once everyone has chosen, all reveal simultaneously.", [5]),
    ("In a seven-player vote, Red receives three votes, Blue two and Green two. Is a four-vote majority necessary to make Red a Target? Explain the Target threshold.", "No majority is required: the greatest vote total determines the Target. Red alone is Target because three is the highest count.", [5]),
    ("Red and Blue tie for the most votes. With neither playing Ambush, what happens to them, and may someone survive by having voted for either tied Target?", "Both tied Targets are eliminated. A non-Target voter who voted for either tied Target satisfies the voting requirement and is not eliminated for voting outside the Target group.", [5, 6]),
    ("Blue is the sole Target. Green received no votes and voted for Red. Green did not Ambush. Does receiving no votes keep Green alive?", "No. A player who did not vote for a Target is also eliminated, even when nobody voted for that player. Green voted outside the Target group and is eliminated.", [5]),
    ("Red plays Ambush, Yellow votes for Red, and Pink votes for Yellow. How are votes tallied, who are the Targets, and who survives after Red's legal retaliation?", "Ambush adds no vote. Red and Yellow each have one vote and are tied Targets. Yellow is eliminated; Red survives its successful Ambush and can retaliate only against Yellow, who voted for Red. Pink voted for tied Target Yellow and survives, leaving Red and Pink.", [6]),
    ("A Target successfully plays Ambush and four players voted for them. Do they eliminate all four voters? May they choose a player who voted for another color instead?", "The ambusher survives and eliminates exactly one of the players who voted for them. They neither eliminate every voter nor choose someone who did not vote for them.", [6]),
    ("A player chooses Ambush but is not among the Targets after the votes are counted. What happens to that player?", "The Ambush fails and that player eliminates themselves.", [6]),
    ("Four players survive a vote and its Ambush effects. Does the round award gold now, and who participates next?", "The round continues with another conspiracy and vote among the four survivors. It ends when the resolved vote leaves one, two or no survivors.", [4, 5]),
    ("Exactly one player survives the round. What reward do they collect, and are the four cards four points?", "The sole survivor collects all four central Gold Bar cards. Four bars are four cards, not four points; each Gold Bar is worth 3, 4 or 5 points.", [3, 4, 8]),
    ("Exactly two players survive the voting. What must they do, which cards does each receive, and how do they choose and reveal?", "They must hold a Final Showdown. Each receives Share, Steal and Grab One & Go, may discuss intentions, secretly chooses one card face down, and reveals simultaneously with the other finalist.", [7, 8]),
    ("The final vote eliminates every participant. Who receives gold from the deck, who does not, and what happens to the four central bars for next round?", "Nobody receives the central bars. Every player not involved in that final vote receives one Gold Bar from the deck; participants in that final vote receive none. Leave the four central bars and add no new central gold next round.", [4]),
    ("Both finalists reveal Share. How many Gold Bar cards does each receive?", "Each finalist receives two of the four central Gold Bar cards.", [8]),
    ("One finalist reveals Share and the other Steal. How are the central Gold Bars divided?", "The Share player receives no bars and the Steal player receives all four.", [8]),
    ("One finalist reveals Grab One & Go and the other Steal. How are the central Gold Bars divided?", "Grab One & Go receives one bar and Steal receives three.", [8]),
    ("One finalist reveals Grab One & Go and the other Share. How are the central Gold Bars divided?", "Grab One & Go receives one bar and Share receives three.", [8]),
    ("Both finalists reveal Grab One & Go. How many bars does each take, how many remain central, and how many new central bars are dealt if play continues?", "Each takes one central bar. Leave the other two central and deal just two new central bars for the next round.", [8]),
    ("Both finalists reveal Steal. What do the finalists and the other players receive, and what happens to the central pot?", "Both finalists receive nothing. Each other player receives one Gold Bar from the deck. Leave all four central bars for the next round rather than replacing them.", [8]),
    ("When is victory checked, what totals win with 6–9 versus 10–12 players, and who wins if multiple players qualify with different totals?", "Check at round end after Gold Bar awards. The threshold is 25 points with 6–9 players and 24 with 10–12. When several qualify, the highest total wins.", [4, 8]),
    ("At game end exactly two qualifying players tie for the highest Gold point total. What does the booklet require? If a normal round ends without a winner, which eliminated players return?", "The tied players conduct another Final Showdown, repeating until a single player at the table has the highest Gold point total. If no winner ends the game, every player returns next round: stand all IDs upright again.", [4, 8]),
]
questions = {"game": "Dead Last", "scope": "Complete English base game, publisher Rules 2.0 (2016). No expansions or optional modes.", "benchmark_version": "coordinator-seed-v1", "questions": [{"id": f"Q{i:02}", "question": question} for i, (question, answer, pages) in enumerate(entries, 1)]}
answers = {"game": "Dead Last", "benchmark_version": "coordinator-seed-v1", "prepared_before_agent_answers": True, "prepared_by": "Batch coordinator, after complete source PDF/text and visual voting/payoff checks; coordinator also authored the new unverified summary baseline.", "grading": "Correct only if every requested material part is resolved accurately with summary support; partial for missing/unresolved parts; incorrect for any contradictory material ruling. Confidence/support labels alone are not grades.", "answers": [{"id": f"Q{i:02}", "answer": answer, "source_references": [{"path": "source_pdfs/dead-last-rules.pdf", "pdf_pages": pages}], "novelty": "Distinct procedural rule, source-defined outcome branch, or consequential voting interaction."} for i, (question, answer, pages) in enumerate(entries, 1)]}
(base / "questions.json").write_text(json.dumps(questions, indent=2) + "\n")
(base / "answer-key.json").write_text(json.dumps(answers, indent=2) + "\n")
paths = [base / "questions.json", base / "answer-key.json", Path("source_pdfs/dead-last-rules.pdf"), Path("extracted/dead-last-rules.txt"), Path("rules/dead-last.md")]
(base / "input-manifest.json").write_text(json.dumps({"hashes": {str(path.resolve()): hashlib.sha256(path.read_bytes()).hexdigest() for path in paths}, "status": "Coordinator preparation; worker must verify source/key and version any genuine correction before testing."}, indent=2) + "\n")
lines = ["# Dead Last coordinator seed", "", "This is preparation for the queued game chat, not a test result or independent audit. The game evaluator must verify every entry against the full PDF, retain all historical entries, and independently expand/review coverage under the QA guide.", ""]
for question, answer in zip(questions["questions"], answers["answers"]):
    lines.extend([f'## {question["id"]}', "", question["question"], "", answer["answer"], "", "Source PDF pages: " + ", ".join(map(str, answer["source_references"][0]["pdf_pages"])), ""])
(base / "question-bank.md").write_text("\n".join(lines))
print(base.resolve())
